from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class TrsnwParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        enb_id = self.enb_ent_config['id']

        if self.enb_ent_config['is_ipv4']:
            ipV4AddressDN1 = f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1'
            self.set_struct_parameter('cPlane', 'ipV4AddressDN1', ipV4AddressDN1)
            self.set_struct_parameter('uPlane', 'ipV4AddressDN1', ipV4AddressDN1)

        if self.enb_ent_config['is_ipv6']:
            ipV6AddressDN1 = f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV6-1'
            self.set_struct_parameter('cPlane', 'ipV6AddressDN1', ipV6AddressDN1)
            self.set_struct_parameter('uPlane', 'ipV6AddressDN1', ipV6AddressDN1)
